(async () => {
  const db = new ClassicLevel(PACK_PATH, { valueEncoding: "utf8" });
  await db.open();
  try {
    const dels = [];
    for await (const [k] of db.iterator()) if (!k.startsWith("!folders!")) dels.push(k);
    const ops = dels.map((k) => ({ type: "del", key: k }));
    for (const item of items) ops.push({ type: "put", key: `!items!${item._id}`, value: JSON.stringify(item) });
    await db.batch(ops);
    const counts = { Armor: 0, Consumables: 0, Equipment: 0, Tools: 0, Traps: 0, Weapons: 0, "Sealed Artifacts": 0 };
    for await (const [, v] of db.iterator()) {
      const p = JSON.parse(v);
      if (!p.folder) continue;
      if (p.folder === F.armor) counts.Armor++;
      if (p.folder === F.consumables) counts.Consumables++;
      if (p.folder === F.equipment) counts.Equipment++;
      if (p.folder === F.tools) counts.Tools++;
      if (p.folder === F.traps) counts.Traps++;
      if (p.folder === F.weapons) counts.Weapons++;
      if (p.folder === F.artifacts) counts["Sealed Artifacts"]++;
    }
    console.log(`Inserted items: ${items.length}`);
    console.log(JSON.stringify(counts, null, 2));
  } finally {
    await db.close();
  }
})().catch((err) => { console.error(err); process.exit(1); });
